"use client";
import { useState } from "react";
import {
  AgentProvider,
  useAgentActions,
  useAgentState,
} from "@agentdock-ai/react";
import type { ChatProps } from "./types";
import { ChatShell } from "./chat-shell";
import { ChatViewport } from "./chat-viewport";
import { MessageList } from "./message-list";
import { EmptyState, Suggestions } from "./empty-state";
import { Composer } from "./composer";
import { ErrorState } from "./error-state";

export function Chat(props: ChatProps) {
  return (
    <AgentProvider store={props.store}>
      <ChatSurface {...props} />
    </AgentProvider>
  );
}
function ChatSurface({
  adapter,
  className,
  disabled,
  showReasoning = true,
  suggestions,
  welcomeTitle,
  welcomeDescription,
  placeholder,
}: ChatProps) {
  const { renderModel: model, agent, streamStatus } = useAgentState();
  const actions = useAgentActions(adapter);
  const [draft, setDraft] = useState("");
  const active =
    actions.busy ||
    (streamStatus === "consuming" &&
      !["completed", "failed", "cancelled"].includes(agent.status));
  const waiting = agent.status === "waiting" && streamStatus !== "stopped";
  const items = model.turns.at(-1)?.items ?? [];
  const activity = items.some(
    (item) =>
      item.type === "tool-call" ||
      item.type === "tool-timeline" ||
      item.type === "approval" ||
      (item.type === "message" &&
        item.role === "assistant" &&
        item.blocks.some((b) => b.type !== "reasoning" || showReasoning)),
  );
  const empty = model.turns.length === 0;
  const latestUserId = model.messages
    .filter((m) => m.role === "user")
    .at(-1)?.id;
  async function submit(text: string) {
    if (disabled || active || waiting || !text.trim()) return;
    setDraft("");
    const successful = await actions.sendMessage(text);
    if (!successful) setDraft((current) => current || text);
  }
  const status = actions.cancelling
    ? "Stopping…"
    : actions.respondingTo
      ? "Sending response…"
      : waiting
        ? "Waiting for your response"
        : active
          ? "Agent is working"
          : streamStatus === "error"
            ? "Connection interrupted"
            : streamStatus === "stopped"
              ? "Stream stopped"
              : agent.status === "completed"
                ? "Response complete"
                : agent.status === "failed"
                  ? "Run failed"
                  : agent.status === "cancelled"
                    ? "Run stopped"
                    : "";
  return (
    <ChatShell
      className={className}
      empty={empty}
      footer={
        <>
          {empty && (
            <EmptyState title={welcomeTitle} description={welcomeDescription} />
          )}
          <Composer
            key="composer"
            value={draft}
            onChange={setDraft}
            onSubmit={() => {
              void submit(draft);
            }}
            onStop={
              actions.canCancel && agent.runId
                ? () => {
                    void actions.cancelRun();
                  }
                : undefined
            }
            busy={active}
            waiting={waiting}
            cancelling={actions.cancelling}
            disabled={disabled}
            placeholder={placeholder}
          />
          {empty && suggestions && (
            <Suggestions
              suggestions={suggestions}
              disabled={disabled || active}
              onSubmit={(text) => {
                void submit(text);
              }}
            />
          )}
          <span
            role="status"
            aria-live="polite"
            aria-atomic="true"
            className="sr-only"
          >
            {status}
          </span>
        </>
      }
    >
      <ChatViewport revision={model} latestUserId={latestUserId} empty={empty}>
        {!empty && (
          <MessageList
            model={model}
            thinking={active && !activity}
            showReasoning={showReasoning}
            canRespond={
              actions.canRespond &&
              !active &&
              !disabled &&
              streamStatus !== "stopped"
            }
            respondingTo={actions.respondingTo}
            approvalError={
              actions.actionError?.scope === "approval"
                ? actions.actionError.message
                : undefined
            }
            onRespond={(id, decisions) => {
              void actions.respondToInterrupt(id, decisions);
            }}
          />
        )}
        {model.transportError && actions.actionError?.scope !== "approval" && (
          <ErrorState {...model.transportError} />
        )}
        {actions.actionError?.scope === "cancel" && (
          <ErrorState
            title="Unable to stop"
            detail={actions.actionError.message}
          />
        )}
      </ChatViewport>
    </ChatShell>
  );
}

"use client";
import { useId, useLayoutEffect, useRef } from "react";
import { ArrowUp, Square } from "lucide-react";
import { Button } from "./ui/button";
import { Textarea } from "./ui/textarea";
export function Composer({
  value,
  onChange,
  onSubmit,
  onStop,
  busy,
  waiting,
  cancelling,
  disabled,
  placeholder = "Send a message…",
}: {
  value: string;
  onChange: (text: string) => void;
  onSubmit: () => void;
  onStop?: () => void;
  busy: boolean;
  waiting: boolean;
  cancelling: boolean;
  disabled?: boolean;
  placeholder?: string;
}) {
  const input = useRef<HTMLTextAreaElement>(null);
  const composing = useRef(false);
  const hint = useId();
  useLayoutEffect(() => {
    if (input.current) {
      input.current.style.height = "auto";
      input.current.style.height = `${Math.min(input.current.scrollHeight, 192)}px`;
    }
  }, [value]);
  const canSend = !!value.trim() && !busy && !waiting && !disabled;
  return (
    <form
      aria-label="Send a message"
      onSubmit={(event) => {
        event.preventDefault();
        if (canSend) onSubmit();
      }}
      className="rounded-2xl border border-foreground/25 bg-muted/50 p-2 transition-colors focus-within:border-ring motion-reduce:transition-none"
    >
      <Textarea
        ref={input}
        aria-label="Message"
        aria-describedby={hint}
        rows={1}
        value={value}
        disabled={disabled}
        placeholder={placeholder}
        onChange={(event) => onChange(event.target.value)}
        onCompositionStart={() => {
          composing.current = true;
        }}
        onCompositionEnd={() => {
          composing.current = false;
        }}
        onKeyDown={(event) => {
          if (
            event.key === "Enter" &&
            !event.shiftKey &&
            !event.nativeEvent.isComposing &&
            !composing.current &&
            event.keyCode !== 229
          ) {
            event.preventDefault();
            if (canSend) onSubmit();
          }
        }}
      />
      <div className="flex min-h-7 items-center justify-end gap-2 pt-1">
        <p id={hint} className="sr-only">
          {waiting ? (
            "Waiting for your response"
          ) : busy ? (
            "You can write your next message"
          ) : (
            <>
              <span className="hidden sm:inline">Enter to send · </span>Shift +
              Enter for a new line
            </>
          )}
        </p>
        {busy && !waiting && onStop ? (
          <Button
            aria-label={cancelling ? "Stopping run" : "Stop run"}
            title="Stop run"
            variant="primary"
            disabled={cancelling || disabled}
            onClick={onStop}
            className="size-7 min-h-7 rounded-lg px-0 [@media(pointer:coarse)]:size-9"
          >
            <Square size={12} fill="currentColor" aria-hidden="true" />
          </Button>
        ) : (
          <Button
            type="submit"
            variant="primary"
            disabled={!canSend}
            aria-label="Send message"
            title="Send message"
            className="size-7 min-h-7 rounded-lg px-0 [@media(pointer:coarse)]:size-9"
          >
            <ArrowUp size={16} aria-hidden="true" />
          </Button>
        )}
      </div>
    </form>
  );
}

export function EmptyState({
  title = "How can I help you today?",
  description,
}: {
  title?: string;
  description?: string;
}) {
  return (
    <div className="mb-8 px-2 text-center">
      <h1 className="text-[26px] font-semibold leading-9 tracking-[-0.045em] sm:text-[28px]">
        {title}
      </h1>
      {description && (
        <p className="mt-2 text-[13px] leading-5 text-muted-foreground">
          {description}
        </p>
      )}
    </div>
  );
}
export function Suggestions({
  suggestions,
  disabled,
  onSubmit,
}: {
  suggestions: readonly string[];
  disabled?: boolean;
  onSubmit: (text: string) => void;
}) {
  return (
    <div className="mt-3 flex flex-wrap justify-center gap-2">
      {suggestions.map((prompt) => (
        <button
          type="button"
          key={prompt}
          disabled={disabled}
          onClick={() => onSubmit(prompt)}
          className="min-h-8 rounded-lg border border-border px-3 py-1 text-[12px] leading-5 text-muted-foreground outline-none hover:bg-muted/40 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-40"
        >
          {prompt}
        </button>
      ))}
    </div>
  );
}

import { errorDetail } from "./utils";
export function ErrorState({
  title,
  detail,
}: {
  title: string;
  detail: string;
}) {
  return (
    <div
      role="alert"
      className="min-w-0 border-l-2 border-destructive pl-3 text-[13px] leading-5"
    >
      <p className="text-destructive">{title}</p>
      {detail !== title && (
        <p className="mt-1 text-muted-foreground [overflow-wrap:anywhere]">
          {errorDetail(detail)}
        </p>
      )}
    </div>
  );
}

export { Chat } from "./chat";
export type { ChatProps } from "./types";
export { ChatWorkspace } from "./chat-workspace";
export { ThreadSidebar, type ChatThread } from "./thread-sidebar";

import Markdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { safeUrl } from "./utils";
export function MarkdownContent({ text }: { text: string }) {
  return (
    <div className="min-w-0 space-y-3 text-[14px] leading-6 [overflow-wrap:anywhere] [&>*:first-child]:mt-0 [&>*:last-child]:mb-0">
      <Markdown
        remarkPlugins={[remarkGfm]}
        skipHtml
        urlTransform={(url) => safeUrl(url) ?? ""}
        components={{
          h1: ({ children }) => (
            <h2 className="mt-6 text-[15px] font-semibold tracking-tight">
              {children}
            </h2>
          ),
          h2: ({ children }) => (
            <h3 className="mt-6 text-[15px] font-semibold tracking-tight">
              {children}
            </h3>
          ),
          h3: ({ children }) => (
            <h4 className="mt-5 text-[15px] font-semibold">{children}</h4>
          ),
          p: ({ children }) => <p className="my-2">{children}</p>,
          ul: ({ children }) => (
            <ul className="my-2 list-disc space-y-1 pl-6 marker:text-muted-foreground">
              {children}
            </ul>
          ),
          ol: ({ children }) => (
            <ol className="my-2 list-decimal space-y-1 pl-6 marker:text-muted-foreground">
              {children}
            </ol>
          ),
          blockquote: ({ children }) => (
            <blockquote className="my-4 border-l-2 border-border pl-4 text-muted-foreground">
              {children}
            </blockquote>
          ),
          a: ({ href, children }) =>
            href ? (
              <a
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                className="rounded-sm underline decoration-border underline-offset-4 hover:decoration-foreground focus-visible:outline-2 focus-visible:outline-ring"
              >
                {children}
              </a>
            ) : (
              <span>{children}</span>
            ),
          img: ({ alt, src }) => (
            <span className="text-[13px] text-muted-foreground">
              {typeof src === "string" && safeUrl(src) ? (
                <a
                  href={src}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="underline underline-offset-4"
                >
                  {alt || "View image"}
                </a>
              ) : (
                alt || "Image unavailable"
              )}
            </span>
          ),
          pre: ({ children }) => (
            <pre
